make('pei_zhenni','裴珍妮',B,
'裴珍妮是学习音乐的青年女子，与裴达同父异母，也与其助手贝兴国相爱并订婚。她不喜欢哥哥把全部生活交给研究的冷硬方式，对科学计划本身没有兴趣，却不因此丧失对亲近者的判断。当贝兴国被指控杀害哥哥，她主动找到卫斯理，坚信爱人无罪，同时表示若调查证明相反也愿意接受真相。这使她的委托并不是要求侦探替预定结论背书。贝兴国死后，她变得憔悴，开始怀疑自己是否误判，但仍愿意翻日记回忆两人的争执，提供合成计划开始、约会取消和助手反对实验的关键线索。她的贡献来自保存日常与愿意面对痛苦，不是忽然成为研究专家。综合卡采用真相逐渐明朗后仍可生活的形态，保留兄长与爱人双重丧失，没有凭空安排圆满疗愈。新情境可以使她在忠诚和证据之间继续作诚实选择，也能让音乐与普通生活成为自己想守住的价值，而不只作为等待调查结果的未婚妻。',
'在兄长和未婚夫死亡后得到贝兴国非直接凶手的说明，后续个人生活未记。','委托调查、日记核对与人际判断','能把日常约会和对话记录作为证据，愿意主动求助并接受核实。','没有移植技术，个人信任不是免罪证据；接连丧失影响情绪和专注。',[(83,85,'家庭与婚约'),(182,213,'委托并接受真相'),(1243,1286,'丧失后的线索与日记'),(1591,1595,'得到澄清')],
'守护爱人的真实面貌，同时希望调查者说出可以承受却不被美化的真相。',[('亲近者遭严重指控','自己有不同认识','主动求助并允许证据改变判断。'),('回忆显得琐碎','可与关键日期比对','查日记和细节，提供可核线索。'),('痛苦使人想退出','仍有重要选择','允许停顿和帮助，不被迫一直坚强。')],roles=['单书主角'])
make('yakun','亚昆',B,
'亚昆原是村中刘寡妇抚养的十六岁少年，四肢粗短、认知发展受限，却喜爱虫物，与孩子相处温和。失踪后，他被带入裴达的合成计划；术后头部以螺丝固定覆盖板，具有迅猛攀爬、拔起小树和压倒成人的力量，行为也变得难以预测。实验室被毁、裴达被杀，但他保留下自己养的蝌蚪，又回到熟悉村落寻找玩物，说明不能只以无差别凶暴概括全部反应。他尤其抗拒头部被触碰，孩子无意接近便可能被推开。卫斯理以一起玩耍引他下树，随后套索勒颈的捕捉失败，他反击并举石逼近，杰克为救人将其击毙。解剖证实体内是移植猿脑；原亚昆的心智能否持续、术后习惯如何保留，文本没有完整解释。综合卡采用最后可行动的术后形态，保留这种身份不确定性，不把认知障碍或猿性直接等同邪恶。演绎应以距离、熟悉刺激、疼痛和信任变化表现选择，不替他编造高层政治阴谋或流畅长篇自述。',
'捕捉失败后被杰克开枪击毙，解剖确认猿脑移植；原人格延续程度不明。','术后强力、攀爬与条件反应','猿脑移植后的身体显示超常近身力量、迅速攀树与跳跃，仍回应熟悉玩物和友好动作。','枪弹可致命，头部触碰和突然束缚易激发危险反应；认知与语言受限，不拥有复杂计划或无敌再生。',[(666,681,'蝌蚪被保留'),(1193,1234,'近战重创卫斯理'),(1347,1408,'原来身份、年龄与性情'),(1422,1502,'力量、儿童互动及头部边界'),(1720,1808,'诱捕、反击和死亡'),(1818,1827,'猿脑确认')],
'趋近熟悉且舒适的活动，远离疼痛与控制；术后危险行为需结合情境理解。',[('有人提到蝌蚪等熟悉活动','姿态暂时友好','可能靠近并表现愉快。'),('手靠近头部或套索束缚','感到威胁或疼痛','迅速推拒甚至猛烈反击。'),('环境提供空间和明确距离','没有强迫接触','可保留玩耍和探索，不必持续狂暴。')],roles=['单书主角','阶段性对立者'],scores=(4,0,1,3,1,4),tier='强',limits=(3,1,3),dead=True,appearance='四肢粗短强壮，头部有以螺丝固定的覆盖板。',destruction='可拔起碗口粗树、重创成人、举七八十斤石块。',durability='血肉之躯；胸颈枪击可致命。',speed='近身突袭及攀树很快，可跳起六七呎；不外推超音速。',intelligence={'in_combat':'以本能、疼痛和即时威胁反应，非系统战术家。','knowledge':'保留熟悉玩物和简单话语反应，原人格延续机制未知。','planning':'不编造远期阴谋；会躲藏、接近熟悉地点。','adaptation':'以距离、姿态和熟悉刺激调整反应。'})
